#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    long long maxSubarraySumAfterSwaps(std::vector<int>& nums, int k) {
        int n = nums.size();
        long long best = -1e18;
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                std::vector<int> inside(nums.begin() + i, nums.begin() + j + 1);
                std::vector<int> outside;
                for (int idx = 0; idx < i; ++idx) outside.push_back(nums[idx]);
                for (int idx = j + 1; idx < n; ++idx) outside.push_back(nums[idx]);
                std::sort(inside.begin(), inside.end());
                std::sort(outside.rbegin(), outside.rend());
                long long curSum = 0;
                for (int v : inside) curSum += v;
                int swaps = std::min({k, (int)inside.size(), (int)outside.size()});
                for (int s = 0; s < swaps; ++s) {
                    if (outside[s] > inside[s]) curSum += outside[s] - inside[s];
                    else break;
                }
                best = std::max(best, curSum);
            }
        }
        return best;
    }
};

import java.util.*;

class Solution {
    public long maxSubarraySumAfterSwaps(int[] nums, int k) {
        int n = nums.length;
        long best = Long.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                List<Integer> inside = new ArrayList<>();
                for (int idx = i; idx <= j; idx++) inside.add(nums[idx]);
                List<Integer> outside = new ArrayList<>();
                for (int idx = 0; idx < i; idx++) outside.add(nums[idx]);
                for (int idx = j + 1; idx < n; idx++) outside.add(nums[idx]);
                Collections.sort(inside);
                outside.sort(Collections.reverseOrder());
                long curSum = 0;
                for (int v : inside) curSum += v;
                int swaps = Math.min(k, Math.min(inside.size(), outside.size()));
                for (int s = 0; s < swaps; s++) {
                    if (outside.get(s) > inside.get(s)) curSum += outside.get(s) - inside.get(s);
                    else break;
                }
                best = Math.max(best, curSum);
            }
        }
        return best;
    }
}

function maxSubarraySumAfterSwaps(nums, k) {
    const n = nums.length;
    let best = -Infinity;
    for (let i = 0; i < n; i++) {
        for (let j = i; j < n; j++) {
            const inside = nums.slice(i, j + 1).sort((a, b) => a - b);
            const outside = nums.slice(0, i).concat(nums.slice(j + 1)).sort((a, b) => b - a);
            let curSum = inside.reduce((acc, v) => acc + v, 0);
            const swaps = Math.min(k, inside.length, outside.length);
            for (let s = 0; s < swaps; s++) {
                if (outside[s] > inside[s]) curSum += outside[s] - inside[s];
                else break;
            }
            best = Math.max(best, curSum);
        }
    }
    return best;
}
